SIGNS = {}
FOLDER = {}
for folder, slug, name, pointers in ROSTER:
    assert slug not in SIGNS, f"duplicate slug {slug}"
    label, sources = TRADITIONS[folder]
    SIGNS[slug] = (name, f"{label} heroes", pointers, folder, sources)
    FOLDER[slug] = folder

ORDER = [slug for folder in TRADITIONS for (f, slug, _, _) in ROSTER if f == folder]


def out_path(slug):
    return f"{FOLDER[slug]}/{slug}.md"


if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    for slug, (name, status, pointers, folder, sources) in SIGNS.items():
        text = f"""# {name}: research brief

Heroes collection, Anthony 2026-09-17, symbols/heroes/{folder}/. Appended to
PROMPT_TEMPLATE_HEROES.md by tools/codex_dossier_set.py.

---

HERO. {name} ({status}). State at the top the figure's class as the tradition classes it (mortal
hero, demigod, heroized dead with cult, culture hero, epic king) and the earliest secure attestation.

THREADS TO PULL, each to be verified against the sources and dated: {pointers}.

WHERE THE SOURCES ARE for this tradition: {sources}.

STANCE. Legend as fully as fact; nothing discarded for being unprovable, everything labeled.
Where a thread above names a dispute, present both sides with their evidence. Every documented
interaction with another named god or hero gets its own line (the other figure, the nature of the
interaction, the source and date), since sibling dossiers exist for the gods of this tradition in
symbols/pantheon and for the other heroes here, and the files cross-reference by name. Absence of
evidence is a finding.
"""
        open(os.path.join(OUT, f"{slug}.brief.md"), "w").write(text)
    from collections import Counter
    print("wrote", len(SIGNS), "briefs:", dict(Counter(FOLDER.values())))
